'use client';
import { useState, useEffect } from 'react';
import Link from 'next/link';
import { ShieldCheck, Calendar, User, Clock, CheckCircle, XCircle, LayoutDashboard, Building2, Stethoscope, Users, Tag, LogOut, Menu, Activity } from 'lucide-react';

export default function AdminDashboard() {
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    setLoading(true);
    try {
      const res = await fetch('http://localhost:5000/api/bookings'); 
      if (res.ok) {
        const data = await res.json();
        setBookings(data);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
            <h1>Admin Overview</h1>
            <button className="btn btn-outline" onClick={fetchBookings}>Refresh Data</button>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '1.5rem', marginBottom: '3rem' }}>
            <StatCard title="Total Bookings Today" value={Math.ceil(bookings.length * 0.2)} icon={<Calendar color="var(--primary)" />} />
            <StatCard title="Active Users" value={120} icon={<User color="#3498db" />} />
            <StatCard title="Total Revenue" value={`₹${bookings.reduce((sum, b) => sum + Number(b.price), 0)}`} icon={<CheckCircle color="var(--accent)" />} />
            <StatCard title="Commission Earned" value={`₹${Math.floor(bookings.reduce((sum, b) => sum + Number(b.price), 0) * 0.1)}`} icon={<ShieldCheck color="#e67e22" />} />
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '2rem', marginBottom: '2rem' }}>
            {/* Quick Actions */}
            <div className="glass" style={{ padding: '2rem' }}>
                <h3 style={{ marginBottom: '1.5rem', fontSize: '1.2rem' }}>Quick Actions</h3>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '1rem' }}>
                    <Link href="/admin/hospitals" className="btn btn-primary" style={{ display: 'flex', alignItems: 'center', gap: '10px', justifyContent: 'center', textDecoration: 'none' }}>+ Add Hospital</Link>
                    <Link href="/admin/services" className="btn btn-outline" style={{ display: 'flex', alignItems: 'center', gap: '10px', justifyContent: 'center', textDecoration: 'none' }}>+ Add Service</Link>
                    <Link href="/admin/bookings" className="btn btn-outline" style={{ display: 'flex', alignItems: 'center', gap: '10px', justifyContent: 'center', textDecoration: 'none' }}>View Pending</Link>
                    <Link href="/admin/hospitals" className="btn btn-outline" style={{ display: 'flex', alignItems: 'center', gap: '10px', justifyContent: 'center', textDecoration: 'none' }}>Approve Partners</Link>
                </div>
            </div>

            {/* Top Hospitals */}
            <div className="glass" style={{ padding: '2rem' }}>
                <h3 style={{ marginBottom: '1rem', fontSize: '1.2rem' }}>Top Hospitals</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem' }}>
                        <span>Grand City Hospital</span>
                        <span style={{ color: 'var(--accent)' }}>₹45k</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem' }}>
                        <span>Apex Multi-Specialty</span>
                        <span style={{ color: 'var(--accent)' }}>₹32k</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem' }}>
                        <span>City Care Centre</span>
                        <span style={{ color: 'var(--accent)' }}>₹28k</span>
                    </div>
                </div>
            </div>
        </div>

        <h2 style={{ marginBottom: '1.5rem' }}>Recent Bookings</h2>
        {/* Table */}
        <div className="glass" style={{ padding: '0', overflow: 'hidden' }}>
            <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                    <thead>
                        <tr style={{ borderBottom: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.02)' }}>
                            <th style={{ padding: '1rem' }}>ID</th>
                            <th style={{ padding: '1rem' }}>Patient</th>
                            <th style={{ padding: '1rem' }}>Service</th>
                            <th style={{ padding: '1rem' }}>Date</th>
                            <th style={{ padding: '1rem' }}>Price</th>
                            <th style={{ padding: '1rem' }}>Status</th>
                            <th style={{ padding: '1rem' }}>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        {bookings.slice(0, 5).map((booking) => (
                            <tr key={booking.id} style={{ borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                                <td style={{ padding: '1rem', color: 'var(--text-muted)' }}>#{booking.id}</td>
                                <td style={{ padding: '1rem' }}>{booking.patient_name}</td>
                                <td style={{ padding: '1rem' }}>{booking.service_name}</td>
                                <td style={{ padding: '1rem' }}>{new Date(booking.booking_date).toLocaleDateString()}</td>
                                <td style={{ padding: '1rem', fontWeight: 'bold' }}>₹{booking.price}</td>
                                <td style={{ padding: '1rem' }}>
                                    <span style={{ 
                                        padding: '4px 10px', 
                                        borderRadius: '20px', 
                                        fontSize: '0.75rem',
                                        background: booking.status === 'Completed' ? 'rgba(46, 204, 113, 0.2)' : 'rgba(0, 210, 211, 0.2)',
                                        color: booking.status === 'Completed' ? '#2ecc71' : 'var(--primary)'
                                    }}>
                                        {booking.status}
                                    </span>
                                </td>
                                <td style={{ padding: '1rem' }}>
                                    <button className="btn-link" style={{ color: 'var(--text-muted)', fontSize: '0.8rem' }}>View</button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {bookings.length === 0 && (
                    <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-muted)' }}>No bookings found.</div>
                )}
            </div>
      </div>
    </div>
  );
}

function StatCard({ title, value, icon }) {
    return (
        <div className="glass" style={{ padding: '1.5rem', display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <div style={{ width: '50px', height: '50px', borderRadius: '12px', background: 'rgba(255,255,255,0.05)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {icon}
            </div>
            <div>
                <div style={{ color: 'var(--text-muted)', fontSize: '0.9rem' }}>{title}</div>
                <div style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>{value}</div>
            </div>
        </div>
    );
}
